/* Creates fresh synthetic customers (one per domain) on the UI CLONE stack through the real HTTP API (mock mailbox, mock payment) and completes one QUICK diagnosis each; the report is generated by the fake model.
   Writes email/password pairs to /tmp/claude-1000/uiclone/customers.json (mode 600, clone only). usage: API=http://127.0.0.1:4396/api/v1 PGDATABASE=mmri_qa_rc9_uiclone MMRI_MOCK_MAIL_DIR=... node scripts/qa-ui-make-customers.mjs marketing,finance */
import fs from 'node:fs';
const R=new URL('./lib/',import.meta.url).pathname;const {customer,B,sql}=await import(R+'admin-qa.mjs');const {http:api,journey}=await import(R+'qa-journey.mjs');
if(!/mmri_qa_rc9_uiclone/.test(process.env.PGDATABASE||''))throw new Error('REFUSED: clone only');
const out=fs.existsSync('/tmp/claude-1000/uiclone/customers.json')?JSON.parse(fs.readFileSync('/tmp/claude-1000/uiclone/customers.json','utf8')):{};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
for(const d of (process.argv[2]||'marketing').split(',')){
  const cu=await customer('ui'+d);const co=(await api(B,'POST','/companies',{tok:cu.tok,body:{name:'Жишээ '+d+' ХХК'}})).d.id;const j=await journey(B,cu.tok,co,d);
  let st='';for(let i=0;i<60;i++){await sleep(2000);st=sql(`select "generationState" from report_snapshots where "assessmentId"='${j.a}' limit 1`);if(['PASS','AI_FALLBACK_USED','GENERATION_BLOCKED'].includes(st))break}
  out[d]={email:cu.email,password:cu.password,assessmentId:j.a,companyId:co,state:st};console.log(d,st,j.a);
  fs.writeFileSync('/tmp/claude-1000/uiclone/customers.json',JSON.stringify(out,null,1),{mode:0o600});
}
